/// <summary>
/// The data contract class for the batch job
/// </summary>
[DataContractAttribute]
class METBackOrderProcessingDataContract
{
    str packedQuery;
}

Method.Source:
    //CB425 BuyBackOrders
    //boolean includeWeekends;

    /// <summary>
    /// The query object
    /// </summary>
    /// <param name = "_packedQuery">Packed query passed as param</param>
    /// <returns>The query built by UI builder</returns>
    [DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', querystr(METInventSiteBackOrder))]
    public str parmQuery(str _packedQuery = packedQuery)
    {
        packedQuery = _packedQuery;
        return packedQuery;
    }

    //CB425 BuyBackOrders -start
    /*
    /// <summary>
