    /// <returns>true or false</returns>
    [DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:METIncludeWeekends"))]
    public boolean parmIncludeWeekends(boolean _includeWeekends = includeWeekends)
    {
        includeWeekends = _includeWeekends;
        return includeWeekends;
    }*/
    //CB425 BuyBackOrders -end

    /// <summary>
    /// Get the query
    /// </summary>
    /// <returns>Returns the query</returns>
    public Query getQuery()
    {
        return new Query(SysOperationHelper::base64Decode(packedQuery));
    }

/// <summary>
/// Sets the query 
/// </summary>
/// <param name = "_query">Query object to set</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
